import sys
sys.setrecursionlimit(50000)

class Node:

	def __init__(self, val):
		self.right = None
		self.data = val
		self.left = None
		self.nextRight = None

class Solution:

	def connect(self, root):
		queue = [[root]]
		while queue:
			level = queue.pop(0)
			temp = []
			for node in level:
				if node.left:
					temp.append(node.left)
				if node.right:
					temp.append(node.right)
			if temp:
				queue.append(temp)
				for i in range(len(temp) - 1):
					temp[i].nextRight = temp[i + 1]
